<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class WebOrderController extends Controller {
 public function index(Request$r){return response()->json(['success'=>true,'data'=>DB::table('web_orders')->where('company_id',$r->user()->company_id)->latest()->get()]);}
 public function detail(Request$r,int$id){$o=DB::table('web_orders')->where(['id'=>$id,'company_id'=>$r->user()->company_id])->firstOrFail();$o->items=json_decode($o->items,true);$o->history=DB::table('web_order_status_history as h')->leftJoin('users as u','u.id','=','h.user_id')->where('h.web_order_id',$id)->select('h.*','u.name as user_name')->orderBy('h.id')->get();return response()->json(['success'=>true,'data'=>$o]);}
 public function changeStatus(Request$r,int$id){$d=$r->validate(['status'=>'required|in:pending,preparing,packed,ready,delivered,cancelled','notes'=>'nullable']);$c=$r->user()->company_id;$b=$r->user()->branch_id;$u=$r->user()->id;return DB::transaction(function()use($r,$id,$d,$c,$b,$u){$o=DB::table('web_orders')->where(['id'=>$id,'company_id'=>$c])->lockForUpdate()->firstOrFail();abort_if(in_array($o->status,['delivered','cancelled']),422,'El pedido ya está finalizado');$allowed=['pending'=>['preparing','cancelled'],'preparing'=>['packed','cancelled'],'packed'=>['ready','cancelled'],'ready'=>['delivered','cancelled']];abort_unless(in_array($d['status'],$allowed[$o->status]??[]),422,'Transición de estado no permitida');$saleId=$o->sale_id;if($d['status']==='cancelled')DB::table('stock_reservations')->where(['reference_type'=>'web_order','reference_id'=>$id,'status'=>'active'])->update(['status'=>'released','updated_at'=>now()]);if($d['status']==='delivered'){$saleId=$this->convertToSale($r,$o,$c,$b,$u);DB::table('stock_reservations')->where(['reference_type'=>'web_order','reference_id'=>$id,'status'=>'active'])->update(['status'=>'consumed','updated_at'=>now()]);}DB::table('web_orders')->where('id',$id)->update(['status'=>$d['status'],'sale_id'=>$saleId,'payment_status'=>$d['status']==='delivered'?'paid':$o->payment_status,'updated_at'=>now()]);DB::table('web_order_status_history')->insert(['web_order_id'=>$id,'user_id'=>$u,'previous_status'=>$o->status,'new_status'=>$d['status'],'notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('notifications')->insert(['company_id'=>$c,'user_id'=>$u,'type'=>'web_order','title'=>"Pedido {$o->number}: {$d['status']}",'message'=>$d['notes']??"Estado actualizado de {$o->status} a {$d['status']}",'link'=>'Pedidos web','created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Estado del pedido actualizado','data'=>['sale_id'=>$saleId]]);});}
 private function convertToSale(Request$r,object$o,int$c,int$b,int$u):int{$cash=DB::table('cash_sessions')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'open'])->lockForUpdate()->first();abort_unless($cash,422,'Debe abrir caja para entregar y cobrar el pedido');$warehouse=$this->branchWarehouse($c,$b);$series=DB::table('document_series')->where(['company_id'=>$c,'branch_id'=>$b,'document_type'=>'ticket','active'=>1])->lockForUpdate()->firstOrFail();$next=$series->current_number+1;DB::table('document_series')->where('id',$series->id)->update(['current_number'=>$next,'updated_at'=>now()]);$number=$series->series.'-'.str_pad((string)$next,8,'0',STR_PAD_LEFT);$items=json_decode($o->items,true);$fee=round((float)($o->delivery_fee??0),2);$amount=round((float)$o->total-$fee,2);$sale=DB::table('sales')->insertGetId(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'customer_id'=>$o->customer_id,'user_id'=>$u,'number'=>$number,'document_type'=>'ticket','subtotal'=>$amount,'discount'=>0,'tax'=>round($amount*18/118,2),'total'=>$amount,'status'=>'paid','created_at'=>now(),'updated_at'=>now()]);foreach($items as$i){$p=DB::table('products')->where(['id'=>$i['product_id'],'company_id'=>$c])->firstOrFail();$s=DB::table('stocks')->where(['warehouse_id'=>$warehouse->id,'product_id'=>$p->id])->lockForUpdate()->firstOrFail();abort_if($s->quantity<$i['quantity'],422,"Stock insuficiente para {$p->name}");$new=$s->quantity-$i['quantity'];DB::table('stocks')->where('id',$s->id)->update(['quantity'=>$new,'updated_at'=>now()]);app(\App\Services\LotService::class)->consume($c,$warehouse->id,$p->id,(float)$i['quantity'],'sale',$sale);DB::table('sale_details')->insert(['sale_id'=>$sale,'product_id'=>$p->id,'product_name'=>$p->name,'quantity'=>$i['quantity'],'unit_price'=>$i['unit_price'],'entry_mode'=>$i['entry_mode']??'quantity','presentation_id'=>$i['presentation']['id']??null,'presentation_name'=>$i['presentation']['name']??null,'presentation_quantity'=>$i['presentation']['quantity']??null,'presentation_factor'=>$i['presentation']['factor']??null,'historical_unit_cost'=>$p->average_cost,'total'=>$i['total'],'created_at'=>now(),'updated_at'=>now()]);DB::table('inventory_movements')->insert(['uuid'=>Str::uuid(),'company_id'=>$c,'branch_id'=>$b,'warehouse_id'=>$warehouse->id,'product_id'=>$p->id,'user_id'=>$u,'type'=>'web_sale_out','quantity'=>-$i['quantity'],'historical_unit_cost'=>$p->average_cost,'previous_stock'=>$s->quantity,'new_stock'=>$new,'document_type'=>'web_order','document_id'=>$o->id,'document_number'=>$o->number,'created_at'=>now(),'updated_at'=>now()]);}DB::table('sale_payments')->insert(['sale_id'=>$sale,'method'=>'cash','amount'=>$amount,'reference'=>$o->number,'created_at'=>now(),'updated_at'=>now()]);DB::table('cash_movements')->insert(['cash_session_id'=>$cash->id,'type'=>'sale','amount'=>$amount,'description'=>"Pedido web {$o->number}",'reference'=>$number,'user_id'=>$u,'created_at'=>now(),'updated_at'=>now()]);if($fee>0)DB::table('cash_movements')->insert(['cash_session_id'=>$cash->id,'type'=>'income','amount'=>$fee,'description'=>"Delivery del pedido web {$o->number}",'reference'=>$number,'user_id'=>$u,'created_at'=>now(),'updated_at'=>now()]);return$sale;}
}
